'use strict';

// MODULES //

var validateReport = require( '@data-apis/report/validate' );
var originSummary = require( '@data-apis/record/origin-summary' );


// MAIN //

/**
* Derives a dashboard index row from a stored record.
*
* @param {Object} envelope - stored record
* @param {string} recordPath - path relative to data
* @param {Object} [options] - report validation options
* @returns {Object} index row
*/
function indexRecord( envelope, recordPath, options ) {
	var validated = validateReport( envelope.report, options || {} );

	return {
		'library_id': envelope.harvest.library_id,
		'source_id': envelope.harvest.source_id,
		'source_fingerprint': envelope.harvest.source_fingerprint,
		'series_schema': envelope.harvest.series_schema,
		'series_key': envelope.harvest.series_key,
		'origin': originSummary( envelope.harvest.origin ),
		'series': validated.series,
		'timestamp': validated.timestamp,
		'path': recordPath,
		'report_sha256': envelope.harvest.report_sha256,
		'version': envelope.report.version,
		'api_version': envelope.report.api_version,
		'python': envelope.report.python,
		'platform': structuredClone( envelope.report.platform ),
		'execution_target': structuredClone( envelope.report.execution_target ),
		'test_suite': envelope.report.test_suite,
		'summary': structuredClone( envelope.report.data.summary )
	};
}


// EXPORTS //

module.exports = indexRecord;
